"""地球3：語る大地（ワーク p34〜41・45、教科書 p99〜117）"""
from kbank import T, C, SEQ, N, S, R
from sci import unit

MAJ = '語る大地'

def chisou():
    u = unit('chisou', '地層のでき方と広がり', MAJ, {34, 38, 39, 40, 41, 45},
             '2026-10-05 Claude作成。理科ワークp34（教科書チェック①②）・p38〜39要点 地層の広がり・p40基本①と○×①②・p41力だめし②・p45まとめと、教科書p99〜105（地層のでき方と広がり・図43〜46・不整合・観察2・観察のスキル・わたしのレポート・離れた場所の地層の対比と広がり・鍵層・年縞）を写真で確認して作成。柱状図の計算問題は標高と深さの数値を変えて作り、答えをプログラムで確かめた。')
    q = u.q
    q(34, '①(1)', '風化', '地表に出ている岩石が、太陽の熱や水のはたらきにより、長い間に表面や割れ目からくずれたり、とかされたりすることを何というか。', T('風化', 'ふうか'), '教科書p100：これを風化という。', tb=100, tbnote='本文', near=['侵食'])
    q(34, '①(2)', '侵食', '風化によって生じた砕せつ物などが、雨水や流水によってけずりとられることを何というか。', T('侵食', 'しんしょく'), '教科書p100：陸地に降った雨水や流水によってけずりとられ（侵食）、', tb=100, tbnote='本文', near=['風化', '運搬'])
    q(34, '①(3)', '運搬', 'けずりとられた砕せつ物が、流水によって下流へ運ばれることを何というか。', T('運搬', 'うんぱん'), '教科書p100：下流へ運ばれ（運搬）、', tb=100, tbnote='本文', near=['堆積'])
    q(34, '①(4)', '堆積', '砕せつ物が、水の流れがゆるやかになるところで積もることを何というか。', T('堆積', 'たいせき'), '教科書p100：流れがゆるやかになるところで積もって（堆積）、地層をつくる。', tb=100, tbnote='本文', near=['運搬'])
    q(40, '①(2)', '流れる水のはたらき', '岩石が地層になるまでの流れる水のはたらきを、順に並べよう。\nア 運搬　イ 堆積　ウ 侵食', SEQ(list('ウアイ')), 'ワークp40①(2)：（風化した砕せつ物が）侵食→運搬→堆積。', tb=100, tbnote='本文', near=['アウイ', 'ウイア'])
    q(34, '①(1)', '風化', '花こう岩が風化すると、もろくなってばらばらになり、何という土になるか。', T('真砂土', 'まさど', 'まさ土'), '教科書p100写真：花こう岩が風化すると、もろくなってばらばらになり、真砂土になる。', tb=100, tbnote='風化した花こう岩の露頭')
    q(34, '①(5)', '流水がつくる地形', '山地を流れる川が谷底を侵食してできる、V字の形をした谷を何というか。', T('V字谷', 'Ｖ字谷', 'ブイじこく'), '教科書p100図43：V字谷（徳島県三好市）。', tb=100, tbnote='図43', near=['扇状地'])
    q(34, '①(5)', '流水がつくる地形', '川が山地から平地に出たところで、流れが急に遅くなって土砂が堆積してできる扇形の地形を何というか。', T('扇状地', 'せんじょうち'), '教科書p100図43：扇状地（山梨県甲州市、笛吹市）。水の流れが急に遅くなって、堆積が起こる。', tb=100, tbnote='図43', near=['三角州'])
    q(34, '①(5)', '流水がつくる地形', '川が海や湖に流れこむ河口付近に、土砂が堆積してできる地形を何というか。', T('三角州', 'さんかくす'), '教科書p100図43：三角州（滋賀県高島市）。', tb=100, tbnote='図43', near=['扇状地'])
    q(34, '①(1)', '地層のでき方', '河口まで運ばれた水中の砕せつ物のうち、河口から遠くへ運ばれるのは、粒の大きいものと細かいもののどちらか。', T('細かいもの', '細かい粒', 'こまかいもの', '小さいもの', '細かい'), '教科書p101：細かい粒ほど沈みにくく、河口から遠くへ運ばれる。', tb=101, tbnote='本文', near=['大きいもの'])
    q(40, '①(3)', '地層のでき方', 'れき・砂・泥のうち、水中で沈む速さがいちばんおそいのはどれか。', T('泥', 'どろ'), 'ワークp40①(3)：泥（細かい粒ほど沈みにくい）。', tb=101, tbnote='本文', near=['れき', '砂'])
    q(40, '①(4)', '地層のでき方', '海底に積もったれき・砂・泥のうち、海岸（河口）にいちばん近いところに堆積するのはどれか。', T('れき', '礫'), 'ワークp40①(4)ヒント：粒の大きいものほど海岸に近いところに堆積する。', tb=101, tbnote='図44', near=['泥', '砂'])
    q(34, '①(7)', '地層のでき方', '一度に堆積してできた1つの地層の中では、下ほど粒の大きさはどうなるか。', T('大きくなる', '大きい', 'おおきくなる'), '教科書p101：一度に堆積してできた1つの地層の中では、粒の大きなものほど速く沈むため、下ほど粒が大きくなる。', tb=101, tbnote='図45', near=['小さくなる'])
    q(34, '①(7)', '地層のでき方', '一度に堆積してできた1つの地層の中で、下ほど粒が大きくなるのはなぜか。', R((1, ['大き', 'おおき', '重']), (1, ['速く', 'はやく', '先に', 'さきに']), (1, ['沈', 'しず'])), '教科書p101：粒の大きなものほど速く沈むため。', tb=101, tbnote='本文', example='粒の大きなものほど速く沈むから。')
