# ---- 柱状図の計算（標高・深さを変えて作る）----
SITES = [  # (地点の標高, 凝灰岩の上面の深さ, 凝灰岩の厚さ)
    (120, 15, 5), (115, 5, 5), (110, 10, 5), (250, 4, 1), (246, 1, 1), (248, 3, 1),
]
def chuujou(u):
    q = u.q
    pairs = [(0, 1, '西', '東'), (1, 2, '南', '北'), (3, 4, '西', '東'), (2, 0, '北', '南')]
    for k, (i, j, d1, d2) in enumerate(pairs):
        h1, z1, t1 = SITES[i]; h2, z2, t2 = SITES[j]
        k1, k2 = h1 - z1, h2 - z2
        q(38, '①(1)', '鍵層の標高', f'標高{h1} mの地点で、凝灰岩の層の上面は地表から深さ{z1} mにあった。凝灰岩の層の上面の標高は何mか。', N(k1, ['m', 'メートル']), f'標高−深さ＝{h1}−{z1}＝{k1}（m）。地表からの深さ0 mが、その地点の標高を表している（ワークp38）。', tb=104, tbnote='鍵層', near=[str(h1 + z1)])
        if k1 != k2:
            low = d1 if k1 < k2 else d2
            q(39, '②(3)', '地層の傾き', f'{d1}の地点Pは標高{h1} mで、凝灰岩の層の上面が深さ{z1} mにある。{d2}の地点Qは標高{h2} mで、凝灰岩の層の上面が深さ{z2} mにある。地層は東西（または南北）の方向だけに傾いているとすると、地層はどちらの方角に向かって低くなっているか。', T(low, low + '側', low + '向き', low + 'の方'), f'鍵層の標高をそろえて比べる。P：{h1}−{z1}＝{k1} m、Q：{h2}−{z2}＝{k2} m。標高が低い{low}に向かって低くなっている。', tb=104, tbnote='鍵層', near=[d2 if low == d1 else d1])
    q(39, '②(2)', '地層の傾き', '2つの地点で、鍵層（凝灰岩の層）の標高が同じだった。この2地点を結ぶ方向で、地層は傾いているといえるか。', T('傾いていない', 'いえない', '傾いていないといえる', 'かたむいていない', '水平'), 'ワークp39おさえよう：2つの地点で鍵層が同じ標高にあるとき、その方向では地層は傾いていない。', tb=104, tbnote='鍵層', near=['傾いている'])
    q(38, '①(1)', '鍵層の標高', '地点Aの標高は250 mで、凝灰岩の層が地表から深さ5 m〜6 mにある。地点Aの凝灰岩の層の下面の標高は何mか。', N(244, ['m', 'メートル']), '250−6＝244（m）。下面は深さ6 m。', tb=104, tbnote='鍵層', near=['245', '256'])
    q(41, '②(2)', '地層の重なり', '同じ厚さで堆積した地層で、地点Aでは地表から深さ25〜30 mにれき岩の層があり、その下は泥岩の層だった。地点Aの深さ32 mには何の層があると考えられるか。', T('泥岩', 'でいがん', '泥岩の層'), 'ワークp41②(2)：柱状図の下に続く層を考える。30 mより下は泥岩の層。', tb=101, tbnote='柱状図', near=['れき岩'])
    q(41, '②(1)', '鍵層', 'ある地域の柱状図で、凝灰岩の層があることから、その地層が堆積した当時、どのようなできごとがあったことがわかるか。', R((1, ['火山', 'かざん']), (1, ['噴火', 'ふんか'])), 'ワークp41②(1)：凝灰岩は火山灰などが堆積して固まったもの。火山の噴火があったことがわかる。', tb=108, tbnote='凝灰岩', example='火山の噴火があった。')
    # 3地点で傾きの向きを決める（ワークp39②・p41②(5)と同じ考え方）
    THREE = [  # (A:西の標高,深さ) (B:Aの東,標高,深さ) (C:Bの南,標高,深さ)
        ((120, 20), (115, 15), (110, 15), '南'),
        ((110, 5), (115, 15), (105, 5), '東'),
        ((105, 10), (110, 15), (110, 10), '北'),
        ((130, 15), (125, 5), (120, 0), '西'),
    ]
    for (ha, za), (hb, zb), (hc, zc), ans in THREE:
        ka, kb, kc = ha - za, hb - zb, hc - zc
        opp = {'東': '西', '西': '東', '南': '北', '北': '南'}[ans]
        # 傾きはちょうど1方向だけ（東西か南北のどちらか一方だけに差がある）ことを確かめる
        assert (ka == kb) != (kb == kc), (ka, kb, kc)
        got = ('東' if kb < ka else '西') if ka != kb else ('南' if kc < kb else '北')
        assert got == ans, (got, ans)
        q(41, '②(5)', '地層の傾き', f'地点Bは地点Aの真東に、地点Cは地点Bの真南にある。凝灰岩の層の上面の深さは、A（標高{ha} m）で{za} m、B（標高{hb} m）で{zb} m、C（標高{hc} m）で{zc} mだった。地層は同じ厚さで、断層やしゅう曲はなく、一方向に傾いているとする。地層が低くなっている方角を、東・西・南・北から答えよう。', T(ans, ans + '側', ans + '向き'), f'鍵層の標高：A {ha}−{za}＝{ka} m、B {hb}−{zb}＝{kb} m、C {hc}−{zc}＝{kc} m。東西（A−B）と南北（B−C）で比べると、{ans}に向かって低くなっている。', tb=104, tbnote='鍵層', near=[opp])
    q(38, '①(1)', '鍵層の標高', '標高105 mの地点で、凝灰岩の層の上面の標高が92 mだった。この地点で、凝灰岩の層は地表から深さ何mのところにあるか。', N(13, ['m', 'メートル']), '105−92＝13（m）。', tb=104, tbnote='鍵層', near=['197'])
    q(38, '①(2)', '鍵層の標高', '地点Aでは凝灰岩の層の上面の標高が244 m、地点Bは地表の標高が247 mである。地層が水平なとき、地点Bでは凝灰岩の層は地表から深さ何mのところにあるか。', N(3, ['m', 'メートル']), '地層が水平なら、鍵層の標高はどこでも同じ244 m。247−244＝3（m）（ワークp38①(2)と同じ考え方）。', tb=104, tbnote='鍵層', near=['491'])
    q(34, '①(6)', '柱状図', '柱状図で、上下関係は何の上下関係を示しているか。', R((1, ['岩石', '堆積物', '地層', '層'])), '教科書p101の柱状図の説明：岩石や堆積物の上下関係を示す。', tb=101, tbnote='柱状図', example='岩石や堆積物の上下関係')
    q(34, '観察2', '地層の観察', '観察2の考察で、下の層に上の層が堆積するとき、大地にはどのような変化が起きたと考えるか。粒の大きさが上ほど小さくなっている場合、その場所の水深はどうなったと考えられるか。', T('深くなった', 'ふかくなった', '深くなる'), '教科書p101・ワークp34②(2)：粒が小さいものほど岸から遠く深いところに堆積する。上ほど粒が小さい→水深が深くなった（河口から遠くなった）。', tb=101, tbnote='本文', near=['浅くなった'])
    q(34, '観察2', '地層の観察', '地層を観察するときは崖をむやみにさわらないようにし、観察後はどうするか。', R((1, ['きれい', '片づけ', '片付け', 'かたづけ', 'もと'])), '教科書p102吹き出し：観察するときは崖をむやみにさわらないようにね。観察後は、次の人のためにきれいに片づけてね。', tb=102, tbnote='吹き出し', example='次の人のためにきれいに片づける。')
    q(34, '②(1)', '鬼界カルデラ', '鬼界カルデラの海底には、何km³をこえる広範囲に盛り上がった地形ができていることが確認されているか。', N(32, ['km³', 'km3', 'km^3']), '教科書p105なるほど：現在、鬼界カルデラの海底には、32 km³をこえる広範囲に盛り上がった地形ができていることが確認されている。', tb=105, tbnote='なるほど', near=['7325'])
    q(34, '②(1)', '年縞', '水月湖の年縞が、堆積物で浅くなることがないのはなぜか。', R((1, ['断層', 'だんそう']), (1, ['沈降', 'ちんこう', '沈'])), '教科書p105深めるラボ：湖底は断層の動きによって沈降しているため、堆積物で浅くなることはありません。', tb=105, tbnote='深めるラボ', example='断層の動きによって湖底が沈降しているから。')
    q(34, '②(1)', '年縞', '水月湖の年縞は、層の中の花粉や砂などから何を推測することに利用されているか。', T('過去の気候', '気候', 'きこう', 'かこのきこう'), '教科書p105：水月湖の年縞は、層の中の花粉や砂などから過去の気候などを推測することに利用されている。', tb=105, tbnote='深めるラボ')
    q(34, '①(1)', '流れる水のはたらき', '流れる水には、侵食・運搬と、もう1つ何のはたらきがあるか（小学校5年で学習）。', T('堆積', 'たいせき'), '教科書p99つながる学び（小5）：流れる水には、侵食、運搬、堆積のはたらきがある。', tb=99, tbnote='つながる学び', near=['風化'])
    q(34, '①(1)', '地層のでき方', '地層は、水に流されたもののほかに、何から噴出したものが堆積してできることがあるか（小学校6年で学習）。', T('火山', 'かざん'), '教科書p99つながる学び（小6）：地層は、水に流されたものや、火山から噴出したものが堆積してできる。', tb=99, tbnote='つながる学び')

def chisou_full():
    u = chisou(); chuujou(u); return u

def taisekigan():
    u = unit('taisekigan', '地層の岩石', MAJ, {35, 40, 45},
             '2026-10-05 Claude作成。理科ワークp35（教科書チェック①・観察3）・p40基本②と○×②③・p45まとめ⑦と、教科書p106〜108（地層の岩石・図50〜52・観察3・表1 堆積岩の特徴・お仕事ラボ）を写真で確認して作成。')
    q = u.q
    q(35, '①(1)', '堆積岩', 'れき、砂、泥などの層が、長い年月の間に押し固められてできた岩石を何というか。', T('堆積岩', 'たいせきがん'), '教科書p106：このようにしてできた岩石を堆積岩という。', tb=106, tbnote='本文', near=['火成岩'])
    q(35, '①(1)', '堆積岩', '堆積したときは固まっていなかった砕せつ物などの層が固まって岩石になるのは、何によってか。', R((1, ['重み', 'おもみ', '重さ']), (1, ['押し固め', 'おしかため', '押し', '圧'])), '教科書p106：その上に積もった層の重みなどによって、長い年月の間に押し固められたため。', tb=106, tbnote='本文', example='上に積もった層の重みで押し固められる。')
    q(35, '①(2)', '堆積岩', 'れき岩・砂岩・泥岩を、つくっている粒の大きいものから順に並べよう。', SEQ(['れき岩', '砂岩', '泥岩'], seps=('→', '>', '＞', '、', ',', ' ')), '教科書p108表1：れき岩（れき）＞砂岩（砂）＞泥岩（泥）。', tb=108, tbnote='表1', near=['泥岩→砂岩→れき岩'])
    q(35, '①(8)', '堆積岩', '粒の大きさが2 mm以上の粒でできている堆積岩は何か。', T('れき岩', '礫岩', 'れきがん'), 'ワークp35①(8)C・教科書p108表1：れき岩は2 mm以上のれき。', tb=108, tbnote='表1', near=['砂岩'])
    q(35, '①(8)', '堆積岩', '粒の大きさが1/16 mm〜2 mmの粒でできている堆積岩は何か。', T('砂岩', 'さがん'), 'ワークp35①(8)A：砂岩。', tb=108, tbnote='表1', near=['泥岩', 'れき岩'])
    q(35, '①(8)', '堆積岩', '粒の大きさが1/16 mm以下の粒でできている堆積岩は何か。', T('泥岩', 'でいがん'), 'ワークp35①(8)B：泥岩。', tb=108, tbnote='表1', near=['砂岩'])
    q(35, '①(8)', '堆積岩', '泥は粒の大きさによって何と何に分けられるか。2つ答えよう。', S(('シルト', 'しると'), ('粘土', 'ねんど')), '教科書p108表1：泥は粒の大きさによって、シルトと粘土に分けられる。シルトのほうが大きい。', tb=108, tbnote='表1', near=['粘土'])
    q(35, '①(8)', '堆積岩', '泥を分けたシルトと粘土のうち、粒が大きいのはどちらか。', T('シルト', 'しると'), '教科書p108表1：シルトのほうが大きい。', tb=108, tbnote='表1', near=['粘土'])
    q(40, '○×②', '堆積岩', '「れき、砂、泥は、粒の色で分類されている。」この文の誤りを直すと、「色」は何になるか。', T('大きさ', 'おおきさ', '粒の大きさ'), 'ワークp40○×②：粒の大きさ。', tb=108, tbnote='観察3から', near=['色', '形'])
    q(35, '①(9)', '堆積岩の粒', 'れき岩・砂岩・泥岩をつくる粒が、丸みを帯びていることが多いのはなぜか。', R((1, ['運搬', 'うんぱん', '運ばれ', 'はこばれ', '流水', '流れる水']), (1, ['角', 'かど']), (1, ['けずら', '削ら', 'とれ', '取れ'])), '教科書p108：れきなどが運搬される過程で、たがいにぶつかり合うなど、流水のはたらきにともなって角がけずられたため。', tb=108, tbnote='観察3から', example='運搬される間に流水のはたらきで角がけずられたから。')
    q(35, '①(3)', '堆積岩と火成岩', 'れき岩と火成岩のスケッチを比べたとき、粒が丸みを帯びているのはどちらか。', T('れき岩', '礫岩', 'れきがん'), 'ワークp35①(3)(4)：れき岩の粒は丸みを帯びている。火成岩の鉱物は角ばっている。', tb=108, tbnote='観察3から', near=['火成岩'])
    q(35, '①(4)', '堆積岩と火成岩', '火成岩に見られる鉱物と、れき岩・砂岩・泥岩の粒のちがいを、形に注目して書こう。', R((1, ['丸', 'まる']), (1, ['角', 'かど'])), '教科書p108：これらの岩石をつくる粒は、火成岩に見られた鉱物とちがって、丸みを帯びていることが多い。', tb=108, tbnote='観察3から', example='堆積岩の粒は丸みを帯び、火成岩の鉱物は角ばっている。')
    q(35, '①(5)', '石灰岩', '石灰岩とチャートにうすい塩酸をかけたとき、とけて気体が発生したのはどちらか。', T('石灰岩', 'せっかいがん'), '教科書p108：石灰岩はうすい塩酸をかけると、とけて気体（二酸化炭素）を発生する。', tb=108, tbnote='観察3から', near=['チャート'])
    q(35, '①(6)', '石灰岩', '石灰岩にうすい塩酸をかけたときに発生する気体は何か。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), '教科書p108：とけて気体（二酸化炭素）を発生する。', tb=108, tbnote='観察3から', near=['酸素', '水素'])
    q(35, '①(7)', 'チャート', '石灰岩とチャートの表面を鉄くぎでひっかいたとき、傷がつかなかったのはどちらか。', T('チャート', 'ちゃーと'), '教科書p108：チャートはかたく、鉄くぎで表面に傷がつけられず、逆に鉄くぎがけずられてしまう。', tb=108, tbnote='観察3から', near=['石灰岩'])
    q(40, '②(3)', 'チャート', '生物の遺骸や水にとけていた成分が堆積した岩石で、うすい塩酸をかけてもとけない、とてもかたい岩石は何か。', T('チャート', 'ちゃーと'), 'ワークp40②(3)：チャート。', tb=108, tbnote='表1', near=['石灰岩'])
    q(35, '参考', '石灰岩の成分', '石灰岩のおもな成分は何か。', T('炭酸カルシウム', 'たんさんカルシウム'), '教科書p108表1・ワークp35参考：石灰岩のおもな成分は炭酸カルシウム。', tb=108, tbnote='表1', near=['二酸化ケイ素'])
    q(35, '参考', 'チャートの成分', 'チャートのおもな成分は何か。', T('二酸化ケイ素', 'にさんかけいそ'), '教科書p108表1・ワークp35参考：チャートのおもな成分は二酸化ケイ素。', tb=108, tbnote='表1', near=['炭酸カルシウム'])
    q(35, '①(10)', '石灰岩とチャート', '石灰岩やチャートは、何が堆積して固まった岩石か。', R((1, ['生物', 'せいぶつ']), (1, ['遺骸', 'いがい', '死がい', '死骸', '貝がら', '殻']), ), '教科書p108：石灰岩・チャートは、水にとけていた物質や、その物質をもとに体がつくられていた生物の遺骸が、水中に堆積して固まったもの。', tb=108, tbnote='本文', example='生物の遺骸や水にとけていた成分')
    q(35, '①(11)', '凝灰岩', '火山の噴火によって噴出した火山灰などが堆積した後、固まってできた岩石は何か。', T('凝灰岩', 'ぎょうかいがん'), '教科書p108：凝灰岩は、火山の噴火によって噴出した火山灰などが堆積した後、固まったもの。', tb=108, tbnote='本文', near=['石灰岩'])
    q(40, '○×③', '凝灰岩', '「凝灰岩は、貝殻が堆積してできた堆積岩である。」この文の誤りを直すと、「貝殻」は何になるか。', T('火山噴出物', 'かざんふんしゅつぶつ', '火山灰'), 'ワークp40○×③：火山噴出物。', tb=108, tbnote='表1', near=['貝殻'])
    q(35, '①(11)', '凝灰岩', '凝灰岩をつくる粒が、れき岩などとちがって角ばっていることが多いのはなぜか。', R((1, ['火山', '噴火', '火山灰', '火山噴出物']), (1, ['流水', '流れる水', '運搬', '運ばれ', 'けずら', '削ら'])), '教科書p84・108：火山灰は角ばったものが多い。凝灰岩は火山噴出物が堆積したもので、流水で運ばれて角がけずられることがあまりない。', tb=108, tbnote='表1', example='火山灰などが流水で運ばれて角がけずられずに堆積したから。')
    q(35, '①(1)', '堆積岩', '次のうち、堆積岩をすべて選ぼう。\nア 石灰岩　イ 花こう岩　ウ チャート　エ 凝灰岩　オ 安山岩', C('アウエ'), '教科書p106：堆積岩には、れき岩、砂岩、泥岩のほかに、石灰岩、チャート、凝灰岩などがある。花こう岩・安山岩は火成岩。', tb=106, tbnote='本文', near=['アウ', 'アエ', 'ウエ'])
    q(35, '①(1)', '堆積岩', '堆積岩には、生物の遺骸などが何としてふくまれることがあるか。', T('化石', 'かせき'), '教科書p106：生物の遺骸などを化石としてふくむことがある（図51）。', tb=106, tbnote='図51')
    q(35, '①(1)', '堆積岩', '堆積岩をルーペや双眼実体顕微鏡で見て調べることとして、教科書にあげられているものを、次からすべて選ぼう。\nア 粒の有無や形　イ 大きさ　ウ 化石の有無　エ 重さ', C('アイウ'), '教科書p107観察3ステップ1：粒の有無や形、大きさ、化石の有無などを調べる。', tb=107, tbnote='観察3 ステップ1', near=['アイ', 'アウ'])
