def kaseki():
    u = unit('kaseki', '化石と大地の歴史・大地の恵みと災害', MAJ, {36, 37, 40, 41, 45},
             '2026-10-05 Claude作成。理科ワークp36〜37（教科書チェック①〜③・まとめ）・p40基本②(4)(5)と○×④・p41力だめし②(3)(4)・p45まとめ⑧と、教科書p109〜117（地層・化石と大地の歴史・示相化石・示準化石・地質年代・図56〜58・大地の恵みと災害・図59〜66・Review）を写真で確認して作成。')
    q = u.q
    q(36, '①(1)', '化石', '地層に残された生物の遺骸や、生物が生活した跡などを何というか。', T('化石', 'かせき'), '教科書p109：地層の中の化石には、生物の遺骸のほか、生物が生活した跡などがある。', tb=109, tbnote='本文')
    q(36, '①(1)', '化石', '教科書の図53で示されている、生物が生活した跡の化石は何の化石か。', R((1, ['ゾウ']), (1, ['あし跡', '足跡', 'あしあと'])), '教科書p109図53：ゾウのあし跡の化石（三重県伊賀市）。', tb=109, tbnote='図53', example='ゾウのあし跡')
    q(36, '①(3)', '示相化石', 'アサリの化石が見つかった地層は、浅い海と深い海のどちらでできたと考えられるか。', T('浅い海', 'あさい海', '浅い'), '教科書p109：アサリの化石が見つかった地層は、浅い海でできたと考えられる。', tb=109, tbnote='本文', near=['深い海'])
    q(36, '①(3)', '示相化石', 'アサリの化石から地層ができた環境を推測できるのは、何と比べることによってか。', R((1, ['現在', 'げんざい', '今']), (1, ['生存', '生き', 'すん', '住ん', '環境'])), '教科書p109：現在アサリが生存する環境と比べることによって推測できる。', tb=109, tbnote='本文', example='現在アサリが生存する環境と比べる。')
    q(36, '①(7)', '示相化石', '地層ができた当時の環境を推測することができる化石を何というか。', T('示相化石', 'しそうかせき'), '教科書p109：このような化石を示相化石という。', tb=109, tbnote='本文', near=['示準化石'])
    q(36, '①(8)', '示相化石', '示相化石になる生物は、生存する場所についてどのような特徴をもつ生物か。', R((1, ['限られ', 'かぎられ', '限定', '決まった', '特定']), (1, ['環境', '場所', 'ところ'])), '教科書p109：ある限られた環境で生存する生物の化石が見つかれば、地層ができた当時の環境を推測できる。', tb=109, tbnote='本文', example='ある限られた環境にしか生存しない生物。')
    q(36, '①(4)', '示相化石', 'サンゴの化石が見つかった地層は、どのような場所でできたと考えられるか。', R((1, ['あたたか', '暖か', '温か']), (1, ['浅', 'あさ'])), '教科書p109図54：サンゴ礁をつくるサンゴは、あたたかくて浅い海にいる。', tb=109, tbnote='図54', example='あたたかくて浅い海')
